parameters.message:
=<!DOCTYPE html>
<html>
<head>
    <meta charset="UTF-8">
    <style>
        * {
            margin: 0;
            padding: 0;
            box-sizing: border-box;
        }

        body {
            margin: 0;
            padding: 20px;
            background: #0a0e17;
            font-family: 'Segoe UI', system-ui, sans-serif;
            min-height: 100vh;
        }

        .email-container {
            width: 100%;
            max-width: 700px;
            margin: 0 auto;
            background: #0f1525;
            border-radius: 20px;
            overflow: hidden;
            box-shadow: 0 20px 50px rgba(0, 0, 0, 0.5);
            border: 1px solid #1e2536;
        }

        /* HEADER */
        .header {
            background: linear-gradient(90deg, #0066ff 0%, #00ccff 100%);
            padding: 40px 30px;
            text-align: center;
        }

        .header h1 {
            color: white;
            font-size: 32px;
            font-weight: 700;
            margin: 0;
            line-height: 1.2;
        }

        .header .subtitle {
            color: rgba(255,255,255,0.9);
            font-size: 16px;
            margin-top: 8px;
            font-weight: 400;
        }

        /* DATA SECTION */
        .data-section {
            padding: 40px 30px;
            background: #141b2d;
        }

        .data-grid {
            display: flex;
            justify-content: space-between;
            gap: 20px;
        }

        .data-card {
            background: rgba(20, 27, 45, 0.9);
            border-radius: 16px;
            padding: 25px 20px;
            text-align: center;
            border: 1px solid rgba(0, 102, 255, 0.3);
            flex: 1;
            min-width: 0;
        }

        .data-icon {
            font-size: 32px;
            margin-bottom: 15px;
            display: block;
            height: 40px;
        }

        .data-label {
            color: #8a9bb0;
            font-size: 13px;
            font-weight: 600;
            text-transform: uppercase;
            letter-spacing: 1px;
            margin-bottom: 12px;
            display: block;
            white-space: nowrap;
            overflow: hidden;
            text-overflow: ellipsis;
        }

        .data-value {
            font-size: 26px;
            font-weight: 700;
            color: white;
            line-height: 1.2;
            word-wrap: break-word;
            overflow-wrap: break-word;
        }

        .time-value {
            color: #00ccff;
            font-size: 20px;
        }

        .noise-value {
            color: #ff3366;
        }

        .limit-value {
            color: #00ff99;
        }

        /* AI SECTION */
        .ai-section {
            padding: 40px 30px;
            background: #0f1525;
            border-top: 1px solid #1e2536;
        }

        .ai-title {
            text-align: center;
            color: white;
            font-size: 22px;
            font-weight: 600;
            margin-bottom: 25px;
            text-transform: uppercase;
            letter-spacing: 2px;
            color: #00ccff;
        }

        .ai-box {
            background: rgba(20, 27, 45, 0.9);
            border-radius: 16px;
            padding: 30px;
            border: 1px solid rgba(0, 204, 255, 0.3);
        }

        .ai-message {
            color: white;
            font-size: 18px;
            line-height: 1.5;
            text-align: center;
            word-wrap: break-word;
            overflow-wrap: break-word;
            font-style: italic;
        }

        /* FOOTER */
        .footer {
            padding: 30px;
            background: #0a0e17;
            border-top: 1px solid #1e2536;
        }

        .footer-info {
            text-align: center;
        }

        .report-time {
            color: #8a9bb0;
            font-size: 14px;
            margin-bottom: 20px;
        }

        .creator {
            color: #00ccff;
            font-size: 20px;
            font-weight: 700;
            margin: 20px 0;
        }

        .disclaimer {
            color: #8a9bb0;
            font-size: 13px;
            line-height: 1.4;
            margin-top: 25px;
            font-style: italic;
        }

        /* RESPONSIVE */
        @media (max-width: 600px) {
            .data-grid {
                flex-direction: column;
                gap: 15px;
            }

            .header h1 {
                font-size: 28px;
            }

            .data-section {
                padding: 30px 20px;
            }

            .ai-section {
                padding: 30px 20px;
            }

            .ai-title {
                font-size: 20px;
            }

            .ai-message {
                font-size: 16px;
            }

            .data-value {
                font-size: 22px;
            }
        }
    </style>
</head>
<body>
    <div class="email-container">
        <!-- HEADER -->
        <div class="header">
            <h1>BARANGAY NOISE INTELLIGENCE</h1>
            <div class="subtitle">Advanced Monitoring System</div>
        </div>

        <!-- DATA SECTION -->
        <div class="data-section">
            <div class="data-grid">
                <div class="data-card">
                    <div class="data-icon">⏰</div>
                    <div class="data-label">Detection Time</div>
                    <div class="data-value time-value">{{ $('CLEANUP').item.json.localTime }}</div>
                </div>

                <div class="data-card">
                    <div class="data-icon">📊</div>
                    <div class="data-label">Noise Intensity</div>
                    <div class="data-value noise-value">{{ $('Webhook').item.json.body.noise }} dB</div>
                </div>

                <div class="data-card">
                    <div class="data-icon">⚠️</div>
                    <div class="data-label">Barangay Limit</div>
                    <div class="data-value limit-value">2500 dB</div>
                </div>
            </div>
        </div>

        <!-- AI SECTION -->
        <div class="ai-section">
            <div class="ai-title">
                AI BARANGAY ANALYSIS
            </div>

            <div class="ai-box">
                <div class="ai-message">
                    {{ $json.output }}
                </div>
            </div>
        </div>

        <!-- FOOTER -->
        <div class="footer">
            <div class="footer-info">
                <div class="report-time">
                    Report Generated: {{ $('CLEANUP').item.json.localTime }}
                </div>

                <div class="creator">
                    CREATED BY: JANSSEN TENORIO
                </div>

                <div class="disclaimer">
                    This is an automated report from the Barangay Noise Monitoring System.
                </div>
            </div>
        </div>
    </div>
</body>
</html>

